INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q580961', 'Agacher Strip War', 'The Agacher Strip War (French: Guerre de la Bande d’Agacher), also known as the Christmas War (French: Guerre de Noël), was a brief conflict fought by Burkina Faso and Mali over a 160-kilometre-long (100 mi) strip of land along the border in northern Burkina Faso from 25 to 30 December 1985. The war ended in a ceasefire.', 1985, 12, 14, 1985, 12, 30, 'day', '14 December 1985 – 30 December 1985', 58, 'https://en.wikipedia.org/wiki/Agacher_Strip_War'),
  ('Q60764387', '1987 Burkinabé coup d''état', 'The 1987 Burkina Faso coup d''état was a violent military coup in Burkina Faso, which took place on 15 October 1987. The coup was organized by Captain Blaise Compaoré against incumbent far-left President Captain Thomas Sankara, his former friend, bandmate, and associate during the 1983 upheaval.', 1987, 10, 15, NULL, NULL, NULL, 'day', '15 October 1987', 47, 'https://en.wikipedia.org/wiki/1987_Burkina_Faso_coup_d''%C3%A9tat'),
  ('Q2579041', '2009–2010 West African meningitis outbreak', 'The 2009–2010 West African meningitis outbreak was an epidemic of bacterial meningitis which occurred in Burkina Faso, Mali, Niger, and Nigeria since January 2009, an annual risk in the African meningitis belt. A total of 13,516 people have been infected with meningitis, and 931 have died.', 2009, 1, NULL, 2010, NULL, NULL, 'month', 'January 2009 – 2010', 43, 'https://en.wikipedia.org/wiki/2009%E2%80%932010_West_African_meningitis_outbreak'),
  ('Q18380506', '2014 Burkinabé uprising', 'The 2014 Burkina Faso uprising was a series of demonstrations and riots in Burkina Faso in October 2014 that quickly spread to multiple cities. They began in response to attempts at changing the constitution to allow President Blaise Compaoré to run again and extend his 27 years in office.', 2014, NULL, NULL, 2014, 11, 3, 'year', '2014', 57, 'https://en.wikipedia.org/wiki/2014_Burkina_Faso_uprising'),
  ('Q89035147', 'Jihadist insurgency in Burkina Faso', 'Since August 2015, an insurgency has been fought between the government of Burkina Faso and Islamist militant groups, including Jama''at Nasr al-Islam wa al-Muslimin (JNIM), Ansarul Islam and the Islamic State – Sahel Province (IS–SP). It is estimated that 30% of the country is controlled by jihadist forces.', 2015, 8, 23, NULL, NULL, NULL, 'day', '23 August 2015', 51, 'https://en.wikipedia.org/wiki/Islamist_insurgency_in_Burkina_Faso'),
  ('Q22082207', '2016 Ouagadougou attacks', 'On 15 January 2016, gunmen armed with heavy weapons attacked the Cappuccino restaurant and the Splendid Hotel in the heart of Ouagadougou, the capital of Burkina Faso. At least 30 people were killed, and 56 wounded; a total of 176 hostages were released after a government counter-attack into the next morning as the siege ended.', 2016, 1, 16, 2016, 1, 16, 'day', '16 January 2016', 56, 'https://en.wikipedia.org/wiki/2016_Ouagadougou_attacks'),
  ('Q36453969', '2017 Ouagadougou attack', 'Nineteen people were killed and 25 others were injured when suspected jihadists opened fire on a Turkish restaurant and hotel in Ouagadougou, Burkina Faso, on 13 August 2017. Police cornered the attackers, who took hostages and then were killed in an ensuing shootout.', 2017, 8, 13, NULL, NULL, NULL, 'day', '13 August 2017', 41, 'https://en.wikipedia.org/wiki/2017_Ouagadougou_attack'),
  ('Q50312175', '2018 Ouagadougou attack', 'On 2 March 2018, at least eight heavily armed militants launched an assault on key locations throughout Ouagadougou, the capital city of Burkina Faso. Targets included the French embassy and the headquarters of Burkina Faso''s military.', 2018, 3, 2, NULL, NULL, NULL, 'day', '2 March 2018', 51, 'https://en.wikipedia.org/wiki/2018_Ouagadougou_attacks'),
  ('Q79830671', 'Arbinda attack', 'On December 24, 2019, militants from the Islamic State in the Greater Sahara attacked the Burkinabe government military base in Arbinda, Sahel Region, Burkina Faso along with the town of Arbinda itself. The attack was halted due to French and Burkinabe air intervention, although 35 civilians were killed in the jihadists'' massacre.', 2019, 12, 24, NULL, NULL, NULL, 'day', '24 December 2019', 39, 'https://en.wikipedia.org/wiki/Arbinda_attack'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q107113646', 'Solhan and Tadaryat massacre', 'On 4 and 5 June 2021, jihadists from Jama''at Nasr al-Islam wal-Muslimin (JNIM) attacked the village of Solhan, Yagha Province, Burkina Faso. At least 160 people were killed in the massacres, making it the deadliest attacks up to that point in the jihadist insurgency in Burkina Faso since the start of the war in 2015.', 2021, 6, 4, 2021, 6, 5, 'day', '4 June 2021 – 5 June 2021', 48, 'https://en.wikipedia.org/wiki/Solhan_and_Tadaryat_massacres'),
  ('Q110663445', 'January 2022 Burkina Faso coup d''état', 'A coup d''état was launched in Burkina Faso on 24 January 2022. Gunfire erupted in front of the presidential residence in the Burkinabé capital Ouagadougou and several military barracks around the city.', 2022, 1, 23, 2022, 1, 24, 'day', '23 January 2022 – 24 January 2022', 62, 'https://en.wikipedia.org/wiki/January_2022_Burkina_Faso_coup_d''%C3%A9tat'),
  ('Q114341504', 'September 2022 Burkina Faso coup d''état', 'A coup d''état took place in Burkina Faso on 30 September 2022, removing Interim President Paul-Henri Sandaogo Damiba over his alleged inability to deal with the country''s Islamist insurgency. Damiba had come to power in a coup d''état eight months earlier.', 2022, 9, 30, NULL, NULL, NULL, 'day', '30 September 2022', 58, 'https://en.wikipedia.org/wiki/September_2022_Burkina_Faso_coup_d''%C3%A9tat'),
  ('Q129811621', '2024 Barsalogho massacre', 'On 24 August 2024, jihadists from Jama''at Nusrat al-Islam wal-Muslimin (JNIM) killed between 200 and 600 civilians digging trenches for the Burkinabe government around the town of Barsalogho, Sanmatenga Province, Burkina Faso. The massacre is the deadliest in Burkinabe history, and the deadliest attack in the Islamist insurgency in Burkina Faso.', 2024, 8, 24, NULL, NULL, NULL, 'day', '24 August 2024', 45, 'https://en.wikipedia.org/wiki/Barsalogho_massacre');
